/**
 * Drizzle table definitions (docs/ARCHITECTURE.md §5). drizzle-kit generates SQL migrations from this file
 * into /db/migrations; review the generated SQL before committing it.
 *
 * Conventions: UUID primary keys generated by the server (ciphertexts are bound to them, §6.2); timestamps are
 * timestamptz; encrypted fields are a `*_ct` (ciphertext + tag) and `*_nonce` pair of BYTEA columns.
 */
import { sql } from 'drizzle-orm';
import {
  boolean,
  check,
  customType,
  index,
  integer,
  pgEnum,
  pgTable,
  smallint,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from 'drizzle-orm/pg-core';

const bytea = customType<{ data: Buffer; driverData: Buffer }>({ dataType: () => 'bytea' });
const timestamptz = (name: string) => timestamp(name, { withTimezone: true, mode: 'date' });

export const roleEnum = pgEnum('role', ['NORMAL_USER', 'COURSE_LEADER', 'SYS_ADMIN']);
export const themeEnum = pgEnum('theme', ['light', 'dark', 'system']);
export const sessionKindEnum = pgEnum('session_kind', ['browser', 'device']);
/**
 * Second-factor state of a session:
 *  - not_required: the account has no TOTP; the session is complete.
 *  - pending: password accepted, waiting for the authenticator code.
 *  - enrolment_required: a SYS_ADMIN without TOTP; may only set it up.
 *  - verified: TOTP checked in this session.
 */
export const mfaStateEnum = pgEnum('mfa_state', [
  'not_required',
  'pending',
  'enrolment_required',
  'verified',
]);

export const users = pgTable(
  'users',
  {
    id: uuid('id').primaryKey(),
    /** As the user typed it; uniqueness and login are case-insensitive (see index). Immutable. */
    username: text('username').notNull(),
    email: text('email'),
    role: roleEnum('role').notNull(),
    /** argon2id PHC string; includes its own parameters so they can be raised later. */
    passwordHash: text('password_hash').notNull(),
    /** Forgot-password lock-out (spec §4.3): login is refused until a SYS_ADMIN sets a new password. */
    resetPending: boolean('reset_pending').notNull().default(false),
    /** TOTP secret, encrypted with the user's profile DEK. */
    totpSecretCt: bytea('totp_secret_ct'),
    totpSecretNonce: bytea('totp_secret_nonce'),
    totpEnabledAt: timestamptz('totp_enabled_at'),
    /** Last accepted TOTP time step, so a code can't be used twice. */
    totpLastStep: integer('totp_last_step'),
    fontSize: smallint('font_size').notNull().default(18),
    theme: themeEnum('theme').notNull().default('system'),
    /** {familyName, givenName, address, photo} as encrypted JSON. */
    profileCt: bytea('profile_ct').notNull(),
    profileNonce: bytea('profile_nonce').notNull(),
    /** The user's profile DEK, wrapped by PROFILE_KEYRING. */
    profileDekWrapped: bytea('profile_dek_wrapped').notNull(),
    lastLoginAt: timestamptz('last_login_at'),
    createdAt: timestamptz('created_at').notNull().defaultNow(),
    updatedAt: timestamptz('updated_at').notNull().defaultNow(),
  },
  (t) => [
    uniqueIndex('users_username_lower_key').on(sql`lower(${t.username})`),
    check('users_font_size_check', sql`${t.fontSize} IN (16, 18, 20, 22)`),
    check(
      'users_totp_pair_check',
      sql`(${t.totpSecretCt} IS NULL) = (${t.totpSecretNonce} IS NULL)`,
    ),
    uniqueIndex('users_email_lower_key')
      .on(sql`lower(${t.email})`)
      .where(sql`${t.email} IS NOT NULL`),
    index('users_role_idx').on(t.role),
  ],
);

export const sessions = pgTable(
  'sessions',
  {
    /** SHA-256 of the random token in the cookie; the token itself is never stored. */
    idHash: bytea('id_hash').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    kind: sessionKindEnum('kind').notNull(),
    /** e.g. "iPhone · Safari", from the user agent at login; shown in Account → Devices. */
    deviceLabel: text('device_label').notNull(),
    csrfToken: text('csrf_token').notNull(),
    mfa: mfaStateEnum('mfa').notNull(),
    createdAt: timestamptz('created_at').notNull().defaultNow(),
    lastSeenAt: timestamptz('last_seen_at').notNull().defaultNow(),
    expiresAt: timestamptz('expires_at').notNull(),
    revokedAt: timestamptz('revoked_at'),
  },
  (t) => [index('sessions_user_idx').on(t.userId), index('sessions_expires_idx').on(t.expiresAt)],
);

export const captchas = pgTable(
  'captchas',
  {
    id: uuid('id').primaryKey(),
    /** HMAC of the answer under SESSION_SECRET; the answer itself is never stored or sent. */
    answerHash: bytea('answer_hash').notNull(),
    expiresAt: timestamptz('expires_at').notNull(),
  },
  (t) => [index('captchas_expires_idx').on(t.expiresAt)],
);
